macro_rules! Config {
    () => {
        # [doc = " The compiler configuration"] pub struct Config { # [doc = " Command line options"] pub opts : config :: Options , # [doc = " Unparsed cfg! configuration in addition to the default ones."] pub crate_cfg : Vec < String > , pub crate_check_cfg : Vec < String > , pub input : Input , pub output_dir : Option < PathBuf > , pub output_file : Option < OutFileName > , pub ice_file : Option < PathBuf > , # [doc = " Load files from sources other than the file system."] # [doc = ""] # [doc = " Has no uses within this repository, but may be used in the future by"] # [doc = " bjorn3 for \"hooking rust-analyzer's VFS into rustc at some point for"] # [doc = " running rustc without having to save\". (See #102759.)"] pub file_loader : Option < Box < dyn FileLoader + Send + Sync > > , # [doc = " The list of fluent resources, used for lints declared with"] # [doc = " [`Diagnostic`](rustc_errors::Diagnostic) and [`LintDiagnostic`](rustc_errors::LintDiagnostic)."] pub locale_resources : Vec < & 'static str > , pub lint_caps : FxHashMap < lint :: LintId , lint :: Level > , # [doc = " This is a callback from the driver that is called when [`ParseSess`] is created."] pub psess_created : Option < Box < dyn FnOnce (& mut ParseSess) + Send > > , # [doc = " This is a callback to hash otherwise untracked state used by the caller, if the"] # [doc = " hash changes between runs the incremental cache will be cleared."] # [doc = ""] # [doc = " e.g. used by Clippy to hash its config file"] pub hash_untracked_state : Option < Box < dyn FnOnce (& Session , & mut StableHasher) + Send > > , # [doc = " This is a callback from the driver that is called when we're registering lints;"] # [doc = " it is called during lint loading when we have the LintStore in a non-shared state."] # [doc = ""] # [doc = " Note that if you find a Some here you probably want to call that function in the new"] # [doc = " function being registered."] pub register_lints : Option < Box < dyn Fn (& Session , & mut LintStore) + Send + Sync > > , # [doc = " This is a callback from the driver that is called just after we have populated"] # [doc = " the list of queries."] pub override_queries : Option < fn (& Session , & mut Providers) > , # [doc = " An extra set of symbols to add to the symbol interner, the symbol indices"] # [doc = " will start at [`PREDEFINED_SYMBOLS_COUNT`](rustc_span::symbol::PREDEFINED_SYMBOLS_COUNT)"] pub extra_symbols : Vec < & 'static str > , # [doc = " This is a callback from the driver that is called to create a codegen backend."] # [doc = ""] # [doc = " Has no uses within this repository, but is used by bjorn3 for \"the"] # [doc = " hotswapping branch of cg_clif\" for \"setting the codegen backend from a"] # [doc = " custom driver where the custom codegen backend has arbitrary data.\""] # [doc = " (See #102759.)"] pub make_codegen_backend : Option < Box < dyn FnOnce (& config :: Options) -> Box < dyn CodegenBackend > + Send > > , # [doc = " Registry of diagnostics codes."] pub registry : Registry , # [doc = " The inner atomic value is set to true when a feature marked as `internal` is"] # [doc = " enabled. Makes it so that \"please report a bug\" is hidden, as ICEs with"] # [doc = " internal features are wontfix, and they are usually the cause of the ICEs."] pub using_internal_features : & 'static std :: sync :: atomic :: AtomicBool , # [doc = " All commandline args used to invoke the compiler, with @file args fully expanded."] # [doc = " This will only be used within debug info, e.g. in the pdb file on windows"] # [doc = " This is mainly useful for other tools that reads that debuginfo to figure out"] # [doc = " how to call the compiler with the same arguments."] pub expanded_args : Vec < String > , }
    };
}

Config!();